import{_ as t,C as n,o as s,c as r,E as o,a2 as i}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"开源工程观察周报 001 — 持久化智能体运行时正在成为基础能力","description":"","frontmatter":{"title":"开源工程观察周报 001 — 持久化智能体运行时正在成为基础能力","date":"2026-08-02","column":"open-source-engineering","category":"weekly","summary":"LangGraph、OpenHands、CrewAI 与 AutoGen 共同显示，智能体系统正从短生命周期模型循环转向持久状态、受控中断、恢复、隔离与结构化运行。","sources":["LangGraph persistence and human-in-the-loop documentation","OpenHands runtime and sandbox architecture","CrewAI flows and production documentation","AutoGen state and logging documentation"],"outline":"deep","cover":"/assets/covers/durable-agent-runtime-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-02-durable-agent-runtime.md","filePath":"zh/engineering/2026-08-02-durable-agent-runtime.md","lastUpdated":1787407830000}'),l={name:"zh/engineering/2026-08-02-durable-agent-runtime.md"};function p(d,a,h,c,g,u){const e=n("ArticleCover");return s(),r("div",null,[o(e,{image:"/assets/covers/durable-agent-runtime-cover-v2.jpg",kicker:"开源工程观察 · 周报 001",title:"持久化智能体运行时正在成为基础能力",summary:"持久化、检查点、中断、恢复、隔离环境与结构化运行正在成为智能体运行时的标准设施。",version:"EW001",status:"发布于 2026-08-02",languageHref:"/en/engineering/2026-08-02-durable-agent-runtime",languageLabel:"English"}),a[0]||(a[0]=i(`<h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>本周最重要的开源工程信号，不是模型推理能力再次提升，而是智能体系统开始摆脱短生命周期模型循环。工程关注点正在转向：状态保存在哪里、执行在哪里暂停、失败后如何恢复、高风险动作如何审核，以及工具究竟运行在什么环境中。</p><p>LangGraph 将持久化、检查点、人工中断和容错恢复作为运行时基础能力；OpenHands 将智能体逻辑与隔离执行环境分开；CrewAI 将智能体团队与持久流程、生产部署结合；AutoGen 提供状态保存与加载、团队控制、终止条件、跟踪日志和结构化事件日志。</p><p>本周判断是：</p><blockquote><p>生产级智能体运行时已不能只由工具调用定义。它至少必须具备持久状态、中断、恢复、隔离、可观测和明确完成控制。</p></blockquote><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本周选择以下官方材料，因为它们描述了具体运行机制，而不只是产品宣传：</p><ol><li><strong>LangGraph 持久化与人工参与文档</strong>：检查点、工作线程、待处理写入、故障恢复、批准/编辑/拒绝与继续执行。</li><li><strong>OpenHands 运行时与隔离环境文档</strong>：Docker 隔离、进程与远程隔离环境、运行时插件、命令执行和服务暴露。</li><li><strong>CrewAI 文档</strong>：有状态流程、长流程恢复、护栏、人工触发、可观测与部署。</li><li><strong>AutoGen 文档</strong>：团队状态、保存/加载、终止条件、跟踪日志与结构化事件日志。</li></ol><p>这些资料可以证明公开机制的存在，但不能独立证明它们在所有生产负载下都达到相同可靠性。</p><h2 id="本周重点" tabindex="-1">本周重点 <a class="header-anchor" href="#本周重点" aria-label="Permalink to &quot;本周重点&quot;">​</a></h2><h3 id="_1-持久化正在进入运行时核心" tabindex="-1">1. 持久化正在进入运行时核心 <a class="header-anchor" href="#_1-持久化正在进入运行时核心" aria-label="Permalink to &quot;1. 持久化正在进入运行时核心&quot;">​</a></h3><p>LangGraph 将图状态以检查点形式按工作线程保存，从而支持中断、记忆、历史状态调试和故障恢复。待处理写入可以避免同一计算步骤中已经成功的节点在其他节点失败后被重复执行。</p><p>AutoGen 支持保存和加载智能体、团队与终止条件。CrewAI 流程也强调状态管理、持久化和长流程恢复。</p><p>共同方向已经清楚：运行时状态必须跨越单次模型响应与单个进程生命周期。</p><h3 id="_2-人工审核正在成为执行状态" tabindex="-1">2. 人工审核正在成为执行状态 <a class="header-anchor" href="#_2-人工审核正在成为执行状态" aria-label="Permalink to &quot;2. 人工审核正在成为执行状态&quot;">​</a></h3><p>LangGraph 的人工参与中间件可以在敏感工具调用之前暂停，并在批准、编辑或拒绝后恢复。这不是一个简单确认弹窗，而是把图状态持久化，让执行能够安全停止并从同一工作线程继续。</p><p>CrewAI 也把人工触发放入任务与流程控制中。其工程模式是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拟执行动作</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>政策判断</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>持久化中断</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>人工决定</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>恢复 / 修改 / 拒绝</span></span></code></pre></div><p><em>图：JoinWell52 研究中心根据官方运行时文档整理。</em></p><h3 id="_3-隔离正在成为运行时正确性的一部分" tabindex="-1">3. 隔离正在成为运行时正确性的一部分 <a class="header-anchor" href="#_3-隔离正在成为运行时正确性的一部分" aria-label="Permalink to &quot;3. 隔离正在成为运行时正确性的一部分&quot;">​</a></h3><p>OpenHands 在隔离环境中执行命令、修改文件和启动服务。Docker 是推荐隔离方案；进程模式更快但被明确标记为不安全；远程隔离环境支持托管运行。</p><p>这说明工具能力与执行安全不能在事后分离。运行时必须知道动作在哪里执行，以及适用什么隔离边界。</p><h3 id="_4-可观测正在分成跟踪记录与结构化事件" tabindex="-1">4. 可观测正在分成跟踪记录与结构化事件 <a class="header-anchor" href="#_4-可观测正在分成跟踪记录与结构化事件" aria-label="Permalink to &quot;4. 可观测正在分成跟踪记录与结构化事件&quot;">​</a></h3><p>AutoGen 区分面向开发者阅读的跟踪日志与面向其他系统消费的结构化事件。CrewAI 强调生产流程的可观测性；LangGraph 将检查点执行连接到跟踪与调试。</p><p>两者用途不同：日志帮助人理解，结构化事件支持自动处理、指标、告警和治理。</p><h2 id="交叉分析" tabindex="-1">交叉分析 <a class="header-anchor" href="#交叉分析" aria-label="Permalink to &quot;交叉分析&quot;">​</a></h2><h3 id="运行时能力矩阵" tabindex="-1">运行时能力矩阵 <a class="header-anchor" href="#运行时能力矩阵" aria-label="Permalink to &quot;运行时能力矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>运行时能力</th><th>LangGraph</th><th>OpenHands</th><th>CrewAI</th><th>AutoGen</th></tr></thead><tbody><tr><td>持久状态</td><td>工作线程检查点与状态快照</td><td>隔离环境执行周边的会话和状态</td><td>流程状态与持久化</td><td>智能体与团队状态保存/加载</td></tr><tr><td>中断后恢复</td><td>原生指令恢复</td><td>依部署方式重启运行时或会话</td><td>长流程恢复</td><td>加载已保存的团队状态</td></tr><tr><td>人工审批</td><td>批准/编辑/拒绝式中断</td><td>操作者介入任务执行</td><td>人工参与触发器</td><td>用户代理与团队控制模式</td></tr><tr><td>故障恢复</td><td>检查点与待处理写入恢复</td><td>隔离环境重启与重建</td><td>流程控制和重新部署</td><td>外部终止、重置、状态恢复</td></tr><tr><td>执行隔离</td><td>不是主要抽象</td><td>Docker/进程/远程隔离环境</td><td>依赖部署环境</td><td>依赖代码执行器与运行时</td></tr><tr><td>结构化可观测</td><td>状态历史与跟踪集成</td><td>运行时日志与环境可见性</td><td>内置可观测与托管监控</td><td>跟踪日志与事件日志分离</td></tr><tr><td>完成控制</td><td>图结束状态与节点转换</td><td>智能体/任务完成</td><td>任务/过程/流程完成</td><td>终止条件与团队结果</td></tr></tbody></table><p><strong>说明：</strong> 本表总结官方文档中的机制，不是性能测评。</p><h3 id="最小持久化运行时契约" tabindex="-1">最小持久化运行时契约 <a class="header-anchor" href="#最小持久化运行时契约" aria-label="Permalink to &quot;最小持久化运行时契约&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作身份 / 工作线程</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>持久状态</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>可执行步骤</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>检查点 + 事件</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>政策 / 人工中断</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>恢复、重试或故障恢复</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>有证据的完成</span></span></code></pre></div><p>缺少其中任何一层，仍可以演示智能体，但难以作为长期工作者运行。</p><h2 id="新架构判断" tabindex="-1">新架构判断 <a class="header-anchor" href="#新架构判断" aria-label="Permalink to &quot;新架构判断&quot;">​</a></h2><ol><li><strong>检查点正在成为演示系统与持久系统的分界线。</strong> 运行时必须从已记录状态恢复，而不是重新推理。</li><li><strong>人工审核必须被建模为生命周期状态。</strong> 它不能只是聊天中的约定。</li><li><strong>执行隔离属于运行时契约。</strong> 只有工具权限、没有隔离环境上下文是不完整的。</li><li><strong>结构化事件与人类日志服务不同消费者。</strong> 两者都需要。</li><li><strong>完成需要明确状态转换。</strong> 自然语言“我完成了”不能替代完成证据。</li></ol><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本报告不修改 TMPA 正式出版物。作为研究输入，它强化了中断与恢复过程中事件、生命周期、执行权、完整性与读者重建的重要性。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>数字员工运行时必须跨会话持久保存工作身份、当前状态、待审批动作、工具环境、恢复历史、证据和完成权威。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 已经具有 FCoP 生命周期文件、任务状态、恢复动作、运行时日志与角色化完成门禁。下一步应把检查点、中断、恢复和完成事件统一为稳定运行时契约，而不是分散在操作约定里。</p><h2 id="后续研究" tabindex="-1">后续研究 <a class="header-anchor" href="#后续研究" aria-label="Permalink to &quot;后续研究&quot;">​</a></h2><ol><li>比较不同运行时的检查点粒度与重放语义。</li><li>研究凭据与密钥如何绑定隔离环境和工具。</li><li>比较结构化事件模式与跟踪格式。</li><li>测试多智能体部分失败后的恢复行为。</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>LangChain，<strong>LangGraph overview</strong>：<a href="https://docs.langchain.com/oss/python/langgraph/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langgraph/overview</a></li><li>LangChain，<strong>LangGraph persistence</strong>：<a href="https://docs.langchain.com/oss/python/langgraph/persistence" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langgraph/persistence</a></li><li>LangChain，<strong>Human-in-the-loop</strong>：<a href="https://docs.langchain.com/oss/python/langchain/human-in-the-loop" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langchain/human-in-the-loop</a></li><li>OpenHands，<strong>Runtime Architecture</strong>：<a href="https://docs.openhands.dev/openhands/usage/architecture/runtime" target="_blank" rel="noreferrer">https://docs.openhands.dev/openhands/usage/architecture/runtime</a></li><li>OpenHands，<strong>Sandbox overview</strong>：<a href="https://docs.openhands.dev/openhands/usage/sandboxes/overview" target="_blank" rel="noreferrer">https://docs.openhands.dev/openhands/usage/sandboxes/overview</a></li><li>CrewAI，<strong>Documentation</strong>：<a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">https://docs.crewai.com/</a></li><li>CrewAI，<strong>CrewAI AMP</strong>：<a href="https://docs.crewai.com/enterprise/introduction" target="_blank" rel="noreferrer">https://docs.crewai.com/enterprise/introduction</a></li><li>Microsoft AutoGen，<strong>Managing State</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/state.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/state.html</a></li><li>Microsoft AutoGen，<strong>Logging</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html</a></li></ol>`,45))])}const f=t(l,[["render",p]]);export{b as __pageData,f as default};
